explanation_code:
// 올바른 방법
function useFetch(url) {
  const [data, setData] = useState(null);

  useEffect(() => {
    let cancelled = false;
    fetch(url)
      .then(res => res.json())
      .then(json => {
        if (!cancelled) setData(json);
      });
    return () => { cancelled = true; }; // 클린업
  }, [url]);

  return data;
}

